    22	sub _block_read_only {
    23	    my ($self, $device) = @_;
    24	    my $name = basename($device);
    25	    $name =~ /\A[A-Za-z0-9_.:+-]+\z/ or fatal("unsafe backing device name: $device");
    26	    my $value = read_first_line(cfg('ZRAM_SYSFS_ROOT') . "/class/block/$name/ro");
    27	    return undef if !defined $value || $value !~ /\A[01]\z/;
    28	    return int $value;
    29	}
