    31	sub _mounted {
    32	    my ($self, $device) = @_;
    33	    open my $fh, '<', cfg('ZRAM_PROCFS_ROOT') . '/mounts'
    34	        or fatal('failed to read mount state');
    35	    while (my $line = <$fh>) {
    36	        my ($source) = split /\s+/, $line, 2;
    37	        if (defined $source && same_path($source, $device)) {
    38	            close $fh;
    39	            return 1;
    40	        }
    41	    }
    42	    close $fh;
    43	    return 0;
    44	}
