    46	sub prepare {
    47	    my ($self) = @_;
    48	    $self->mapper()->ensure_open();
    49	    my $device = cfg('ZRAM_BACKING_DEVICE');
    50	    -b $device or fatal("missing zram backing device $device");
    51	    !same_path($device, cfg('ZRAM_SWAP_DEVICE'))
    52	        or fatal('zram swap device and backing device must differ');
    53	    my $read_only = $self->_block_read_only($device);
    54	    defined $read_only && !$read_only or fatal("zram backing device is read-only: $device");
    55	    !$self->_mounted($device) or fatal("zram backing device must not be mounted: $device");
    56	    !swap_active($device) or fatal("zram backing device must not be active swap: $device");
    57	
    58	    if (system('/usr/sbin/blkid', $device) == 0) {
    59	        system('/usr/sbin/wipefs', '-a', '-f', $device) == 0
    60	            or fatal("failed to clear stale signatures from $device");
    61	    }
    62	    return 1;
    63	}
