     8	installer_mapper_for_raw_device() {
     9	  raw_device=$1
    10	  raw_real=$(readlink -f "$raw_device" 2>/dev/null || true)
    11	  [ -n "$raw_real" ] || installer_fatal "unable to resolve encrypted raw device ${raw_device}"
    12	
    13	  mapper_path=
    14	  for dm_sysfs in /sys/class/block/dm-*; do
    15	    [ -d "$dm_sysfs" ] || continue
    16	    [ -r "$dm_sysfs/dm/name" ] || continue
    17	    for slave_sysfs in "$dm_sysfs"/slaves/*; do
    18	      [ -e "$slave_sysfs" ] || continue
    19	      slave_name=${slave_sysfs##*/}
    20	      slave_real=$(readlink -f "/dev/${slave_name}" 2>/dev/null || true)
    21	      [ "$slave_real" = "$raw_real" ] || continue
    22	      dm_name=$(cat "$dm_sysfs/dm/name" 2>/dev/null || true)
    23	      [ -n "$dm_name" ] || continue
    24	      candidate="/dev/mapper/${dm_name}"
    25	      [ -b "$candidate" ] || continue
    26	      if [ -n "$mapper_path" ] && [ "$mapper_path" != "$candidate" ]; then
    27	        installer_fatal "multiple active dm-crypt mappings reference ${raw_device}"
    28	      fi
    29	      mapper_path=$candidate
    30	    done
    31	  done
    32	
    33	  [ -n "$mapper_path" ] || installer_fatal "unable to locate active dm-crypt mapping for ${raw_device}"
    34	  printf '%s\n' "$mapper_path"
    35	}
