    80	sub write_attr_optional {
    81	    my ($path, $value, $desc) = @_;
    82	    _validate_attr_value($desc, $value);
    83	    return 0 if !-e $path || !-w $path;
    84	    if (_dry_run()) {
    85	        log_msg('info', "dry-run: would set $desc via $path to '$value'");
    86	        return 1;
    87	    }
    88	    my $fh;
    89	    if (!open $fh, '>', $path) {
    90	        log_msg('warning', "failed to set optional $desc via $path: $!");
    91	        return 0;
    92	    }
    93	    my $ok = print {$fh} "$value\n";
    94	    $ok = close($fh) && $ok;
    95	    if (!$ok) {
    96	        my $error = $! || 'write rejected';
    97	        log_msg('warning', "failed to set optional $desc via $path: $error");
    98	        return 0;
    99	    }
   100	    return 1;
   101	}
   102	
   103	sub write_attr_required {
   104	    my ($path, $value, $desc) = @_;
   105	    -e $path && -w $path or fatal("$desc is unavailable at $path");
   106	    return 1 if write_attr_optional($path, $value, $desc);
   107	    fatal("failed to set $desc via $path");
   108	}
   109	
   110	sub try_values {
   111	    my ($path, $desc, @values) = @_;
   112	    return 0 if !-e $path || !-w $path;
   113	    my $attempted = 0;
   114	    my $last_error = '';
   115	    for my $value (@values) {
   116	        next if !defined $value || $value eq '';
   117	        _validate_attr_value($desc, $value);
   118	        $attempted = 1;
   119	        if (_dry_run()) {
   120	            log_msg('info', "dry-run: would set $desc via $path to '$value'");
   121	            return 1;
   122	        }
   123	        my $fh;
   124	        if (open $fh, '>', $path) {
   125	            my $ok = print {$fh} "$value\n";
   126	            $ok = close($fh) && $ok;
   127	            return 1 if $ok;
   128	            $last_error = "$!";
   129	        } else {
   130	            $last_error = "$!";
   131	        }
   132	        $last_error = 'write rejected' if $last_error eq '';
   133	    }
   134	    if (!$attempted) {
   135	        log_msg('warning', "no non-empty candidate values supplied for $desc via $path");
   136	    } elsif ($last_error ne '') {
   137	        log_msg('warning', "none of the candidate values worked for $desc via $path: $last_error");
   138	    } else {
   139	        log_msg('warning', "none of the candidate values worked for $desc via $path");
   140	    }
   141	    return 0;
   142	}
