   144	sub zram_fill_pct {
   145	    my $sysfs = cfg('ZRAM_SYSFS');
   146	    my $disksize = read_uint_attr("$sysfs/disksize");
   147	    return 0 if !defined $disksize || $disksize <= 0;
   148	    my $mm_stat = read_first_line("$sysfs/mm_stat");
   149	    return 0 if !defined $mm_stat || $mm_stat !~ /\A([0-9]+)/;
   150	    my $orig_data_size = 0 + $1;
   151	    return int($orig_data_size * 100 / $disksize);
   152	}
   153	
   154	sub recompress_spec {
   155	    my (@specs) = @_;
   156	    return try_values(cfg('ZRAM_SYSFS') . '/recompress', 'zram recompress trigger', @specs);
   157	}
   158	
   159	sub writeback_spec {
   160	    my (@specs) = @_;
   161	    return try_values(cfg('ZRAM_SYSFS') . '/writeback', 'zram writeback trigger', @specs);
   162	}
   163	
   164	sub compact_device {
   165	    my $sysfs = cfg('ZRAM_SYSFS');
   166	    my $changed = 0;
   167	    $changed += write_attr_optional("$sysfs/compact", 1, 'zram compact trigger');
   168	    $changed += write_attr_optional("$sysfs/mem_used_max", 0, 'zram mem_used_max reset');
   169	    return $changed;
