    16	use constant MAX_ATTR_BYTES => 65_536;
    17	
    18	sub _read_attr_bytes {
    19	    my ($path) = @_;
    20	    open my $fh, '<:raw', $path or return undef;
    21	
    22	    my $limit = MAX_ATTR_BYTES + 1;
    23	    my $buffer = '';
    24	    while (length($buffer) < $limit) {
    25	        my $remaining = $limit - length($buffer);
    26	        my $read = read($fh, my $chunk, $remaining);
    27	        if (!defined $read) {
    28	            close $fh;
    29	            return undef;
    30	        }
    31	        last if $read == 0;
    32	        $buffer .= $chunk;
    33	    }
    34	    close $fh or return undef;
    35	    length($buffer) <= MAX_ATTR_BYTES
    36	        or fatal("zram sysfs attribute exceeds byte limit: $path");
    37	    return $buffer;
    38	}
    39	
    40	sub read_first_line {
    41	    my ($path) = @_;
    42	    my $buffer = _read_attr_bytes($path);
    43	    return undef if !defined $buffer;
    44	    my ($line) = split /\n/, $buffer, 2;
    45	    return $line;
    46	}
    47	
    48	sub read_uint_attr {
    49	    my ($path) = @_;
    50	    my $line = read_first_line($path);
    51	    return undef if !defined $line || $line !~ /\A([0-9]+)/;
    52	    return 0 + $1;
    53	}
    54	
    55	sub normalize_attr {
    56	    my ($path) = @_;
    57	    my $buffer = _read_attr_bytes($path);
    58	    return undef if !defined $buffer;
    59	    $buffer =~ s/\s+/ /g;
    60	    $buffer =~ s/\A //;
    61	    $buffer =~ s/ \z//;
    62	    return $buffer eq '' ? undef : $buffer;
    63	}
